INSERT INTO `announcements` (`id`, `announcement_detail`, `active`, `created_at`) VALUES
(5, 'HSC 2028 এর নতুন ব্যাচ আগামী ১লা জুলাই , ২০২৬ থেকে শুরু হবে ইনশাআল্লাহ।  \n\n সময়: শনি-সোম-বুধ\n বিকেল ৫টা থেকে ৬ টা।\n\nআগামী ১লা আগষ্ট , ২০২৬ থেকে - \n\n সময়: রবি – মঙ্গল – বৃহ:\n বিকেল ৫টা থেকে ৬ টা।', 0, '2025-09-09 09:52:51');
