INSERT INTO `sms_templates` (`id`, `category`, `is_active`, `template`, `parent_template`, `default_template`, `default_parent_template`, `send_to_students`, `send_to_parents`, `send_to_test`, `test_phone_number`, `created_at`, `updated_at`) VALUES
(1, 'present', 0, '{student_name}, you are PRESENT today ({date}). Please, ignore previous sms. \n\n- ICT Impulse (Meskath Sir)', 'Dear guardian, \n\n{student_name} is PRESENT today ({date}). Please, ingore previous sms. \n\n- ICT Impulse (Meskath Sir)', 'Dear {student_name}-{student_id}, You were present in {batch_name} batch on {date}. - ICT Impulse', 'Dear Parent, Your child {student_name}-{student_id} was present in {batch_name} batch on {date}. - ICT Impulse', 1, 1, 0, '01723090424', '2025-12-25 05:26:02', '2026-07-02 04:12:46'),
(2, 'payment_confirmation', 1, '{student_name} (S. ID : {student_id}),\n\nYou have paid monthly fee {amount}/= Taka. \nPayment date:  {date}\nThank you. \n\n- ICT Impulse (Meskath Sir)', 'Dear Guardian, \n\n{student_name} has paid monthly fee {amount}/= Taka. \nPayment date: {date}\n\nThank you. \n\n- ICT Impulse (Meskath Sir)', 'Dear {student_name}-{student_id}, Your payment of {amount} BDT for {payment_type} has been received successfully. Date: {date} - ICT Impulse', 'Dear Parent, Payment of {amount} BDT for {student_name}-{student_id} ({payment_type}) received successfully. Date: {date} - ICT Impulse', 1, 1, 0, '01723090424', '2025-12-25 05:37:58', '2026-07-02 04:13:46'),
(3, 'absent', 1, '{student_name}, you are ABSENT today ({date}). Don\'t miss the next class. Be regular.\n\n- ICT Impulse (Meskath Sir)', 'Dear guardian, \n\n{student_name} is ABSENT today ({date}). Please, ensure regular presence at coaching. \n\n- ICT Impulse (Meskath Sir)', 'Dear {student_name}-{student_id}, You were absent from {batch_name} batch on {date}. - ICT Impulse', 'Dear Parent, Your child {student_name}-{student_id} was absent from {batch_name} batch on {date}. - ICT Impulse', 1, 1, 0, '01723090424', '2025-12-25 05:37:59', '2026-07-02 04:12:56'),
(4, 'result', 1, '{student_name},  your ICT {exam_name} result. \nExam Date: {exam_date}\n\nMCQ: {mcq_marks}/{exam_mcq_marks}\nCQ: {cq_marks}/{exam_cq_marks}\nTotal: {total_marks}/{exam_total_marks}\nHighest: {highest_marks}\n\n- ICT Impulse (Meskath Sir)', 'Dear Guardian,\n{student_name}\'s  ICT {exam_name} result. \nExam Date: {exam_date}\n\nMCQ: {mcq_marks}/{exam_mcq_marks}\nCQ: {cq_marks}/{exam_cq_marks}\nTotal: {total_marks}/{exam_total_marks}\nHighest: {highest_marks}\n\n- ICT Impulse (Meskath Sir)', 'Dear {student_name}-{student_id}, Your {payment_type} payment for {month_count} is due. Due Amount: {due_amount} BDT. Please pay as soon as possible. - ICT Impulse', 'Dear Parent, {student_name}-{student_id} {payment_type} payment for {month_count} is due. Due Amount: {due_amount} BDT. Please pay soon. - ICT Impulse', 1, 1, 0, '01723090424', '2025-12-25 05:37:59', '2026-07-02 04:13:23'),
(5, 'due_payment', 1, '{student_name}, \nতোমার ICT Impulse(মেশকাত স্যার) কোচিং এর মাসিক ফি বকেয়া আছে। দ্রুত বকেয়া পরিশোধের অনুরোধ রইলো।', 'সম্মানিত অভিভাবক, \n{student_name} এর ICT Impulse(মেশকাত স্যার) কোচিং এর মাসিক ফি বকেয়া আছে। দ্রুত বকেয়া পরিশোধের অনুরোধ রইলো।', 'Dear {student_name}-{student_id}, Your {payment_type} payment for {month_year} is due. Due Amount: {due_amount} BDT. Please pay as soon as possible. - ICT Impulse', 'Dear Parent, {student_name}-{student_id} {payment_type} payment for {month_year} is due. Due Amount: {due_amount} BDT. Please pay soon. - ICT Impulse', 1, 1, 0, '01723090424', '2025-12-25 06:05:32', '2026-02-21 22:40:00'),
(6, 'batchwise', 1, 'Dear Student, \n\nClasses for your ICT batch resume tomorrow (Saturday, 18/07/2026). Don\'t miss the class!\n\n– ICT Impulse (Meskath Sir)', 'Dear Guardian, \n\nClasses for your childs\' ICT batch resume tomorrow (Saturday, 18/07/2026). \n\n– ICT Impulse (Meskath Sir)', 'Dear {student_name}-{student_id}, {message} - ICT Impulse', 'Dear Parent, Regarding {student_name}-{student_id}: {message} - ICT Impulse', 0, 1, 0, '01723090424', '2025-12-25 19:47:10', '2026-07-16 21:52:19'),
(7, 'admission_confirmation', 1, '{student_name}, welcome to ICT Impulse.  \nAdmission fee {admission_fee}/= received.  \n\nYour student id (S. ID): {student_id}.\n\nVisit www.ictimpulse.com/student-portal for details', 'Dear Guardian,  \n{student_name} has paid {admission_fee}/= taka as admission fee.  \n\nStudent id (S. ID): {student_id}. \n\nThank you for choosing ICT Impulse (Meskat Sir).', 'Dear {student_name}-{student_id}, Congratulations! Your admission to {batch_name} batch has been confirmed. Start Date: {date}. Welcome to ICT Impulse!', 'Dear Parent, Your child {student_name}-{student_id} has been successfully admitted to {batch_name} batch. Start Date: {date}. Welcome to ICT Impulse!', 1, 1, 0, '01723090424', '2026-01-03 13:59:59', '2026-06-27 21:13:33'),
(8, 'exam_absent', 1, '{student_name},  You were ABSENT from ICT {exam_name} exam in date {exam_date}. Be regular and serious. \n\n- ICT Impulse (Meskath Sir)', 'Dear Guardian,\n{student_name} was ABSENT from ICT {exam_name} exam in date {exam_date}. Please, take care. \n\n- ICT Impulse (Meskath Sir)', 'Dear {student_name}-{student_id}, You were absent from {exam_name} exam (Date: {exam_date}) in {batch_name} batch. Please contact your teacher. - ICT Impulse', 'Dear Parent, Your child {student_name}-{student_id} was absent from {exam_name} exam (Date: {exam_date}) in {batch_name} batch. Please contact the teacher. - ICT Impulse', 1, 1, 0, '01723090424', '2026-01-06 14:43:26', '2026-07-02 04:13:33'),
(9, 'attendance', 1, '{student_name}, you are PRESENT today ({date}). Please, ignore today\'s previous sms. \n\n- ICT Impulse (Meskath Sir)', 'Dear guardian, \n\n{student_name} is PRESENT today ({date}). Please, ignore today\'s previous sms. \n\n- ICT Impulse (Meskath Sir)', 'Dear {student_name}-{student_id}, Your manual attendance for {batch_name} batch on {date} has been recorded. - ICT Impulse', 'Dear Parent, Your child {student_name}-{student_id} manual attendance for {batch_name} batch on {date} has been recorded. - ICT Impulse', 1, 1, 0, '01723090424', '2026-05-22 12:20:38', '2026-07-02 04:13:04');
